INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moon-glade', 'north', 'the-white-ride', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moon-glade', 'east', 'the-picked-bones', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-white-ride', 'door', 'The White Ride', 'A ride cut straight through the trees and kept open by nothing anyone can see, the grass down the middle of it grazed short and pale. The moon finds the whole length of it at once. Along both edges the turf is trodden into narrow paths the width of one animal, and they all run the same way.', 0, 0, 'wood', 0, -38, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-ride', 'south', 'the-moon-glade', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-ride', 'east', 'the-gnawed-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gnawed-stand', 'door', 'The Gnawed Stand', 'Young trees standing close, and every one of them is marked at the height of a big dog''s shoulder: bark rubbed through to the wood, and above the rub, long scores where something stood up against the trunk and pulled down. The marks are old on some and white and wet on others. It is a place something comes back to.', 0, 0, 'wood', 0, -37, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-stand', 'west', 'the-white-ride', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-stand', 'south', 'the-picked-bones', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-stand', 'east', 'the-grey-lie', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-picked-bones', 'door', 'The Picked Bones', 'Bones lie in the grass here the way leaves lie anywhere else: long bones split for the marrow, a deer''s skull with the face gone, ribs in a fan. None of it smells. Whatever brings things here eats them down to this and leaves them out, and the grass has grown up through the oldest of it.', 0, 0, 'wood', 0, -37, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picked-bones', 'west', 'the-moon-glade', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picked-bones', 'north', 'the-gnawed-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grey-lie', 'door', 'The Grey Lie', 'A hollow under the roots of a beech that came half down and kept growing, the earth beneath it pressed flat and smooth by a great deal of lying in it. Grey hair is caught in every root. The ground in front of it is bare and beaten, and the bones there are fresh. This is where it sleeps, and it does not sleep far from the door.', 0, 0, 'wood', 0, -36, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-lie', 'west', 'the-gnawed-stand', NULL);
